```rust
#[cfg(windows)]
fn mark_as_from_the_internet(path: &str) {
    // Fails on FAT, exFAT and some shares, which have no alternate streams.
    let _ = std::fs::write(format!("{path}:Zone.Identifier"), "[ZoneTransfer]\r\nZoneId=3\r\n");
}
```

